import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

// The sitemap is generated by scripts/sitemap.mjs (run via the prebuild
// hook), not by vite-plugin-sitemap. The plugin was configured here with
// dynamicRoutes: ['/'] so it only ever emitted the home page, and vite's
// copy of public/sitemap.xml overwrote its output anyway - it looked like
// the sitemap had an owner while nothing was actually maintaining it.
export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
  ],
})
